contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 ether to contract (via fallback)
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "initial deposit failed");

        // Owner sends another account (e.g., address(1)) 0.5 ether from contract via sendMoney
        address target = address(0x1234);
        vm.deal(address(c), 1 ether); // ensure contract has 1 ether
        vm.prank(owner()); // owner is msg.sender of setUp? Actually owner is address who deploys, which is this contract in test
        // But deployer is test contract, so we need to prank as contract itself
        // Simpler: use address(this) as owner via vm.prank(address(this))
        vm.prank(address(this));
        c.sendMoney(target, 0.5 ether, "");

        // Now call withdraw(0.3 ether) as owner
        vm.prank(address(this));
        c.withdraw(0.3 ether);

        // The difference: reference withdraw sends exactly 0.3 ether, bug sends address(this).balance (0.2 ether)
        // After call, owner's balance difference observable if we could check, but we must read c's public state
        // The problem: the property says state variable withdraw differs — but withdraw() is a getter for public state variable of type uint? Actually it's a function, but getter for `withdraw`? No, `withdraw` is a function, not state variable. The only public state variables are owner and depositsCount. So this property is flawed. Correcting to use actual observable: address(c).balance after withdraw.
        // Let's assert that after withdraw(0.3 ether), address(c).balance == 0.2 ether for reference (since sent 0.3) but for bug it would be 0 (since sends entire balance).
        assertTrue(address(c).balance == 0.2 ether, "balance should be 0.2 ether");
    }
    function owner() private view returns (address) {
        return address(this);
    }
}

