import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 ether to a non-payable address (e.g., this contract) via sendMoney
        vm.deal(address(c), 1 ether);
        address target = address(this); // non-payable fallback? sendMoney uses call, will succeed
        vm.prank(c.owner());
        c.sendMoney(target, 1 ether, "");  // transfers entire 1 ether out of C

        // Now address(c).balance == 0
        // Owner calls withdraw(0.5 ether) — reference sends 0.5 ether (but contract has 0, so transfer fails? 
        // Actually transfer will revert if balance insufficient. Let's adjust: instead, we want a successful withdraw.
        // Better: Owner deposits 2 ether via fallback, then sends 1 ether out, leaving 1 ether; 
        // then withdraw(0.5 ether) works for both, but bug sends full 1 ether.
        // Reset: deal 2 ether to c, owner sends 1 ether out -> balance 1; withdraw(0.5) => ref sends 0.5, bug sends 1.

        // Quick fix: start fresh with 2 ether in C
        vm.deal(address(c), 2 ether);
        vm.prank(c.owner());
        c.sendMoney(address(1), 1 ether, "");  // send 1 ether to address(1) (non-payable? call succeeds, ether burnt? Actually address(1) has no code, call will succeed and ether transferred)
        // Now address(c).balance == 1 ether

        uint256 balanceBefore = address(c).balance; // 1 ether
        vm.prank(c.owner());
        c.withdraw(0.5 ether);

        uint256 balanceAfter = address(c).balance;
        // Reference: withdraw(0.5 ether) sends 0.5 ether to owner, so contract left with 0.5 ether
        // Bug: withdraw sends address(this).balance (which is 1 ether before transfer) to owner, so contract left with 0
        // So assert that balanceAfter > 0 (reference) — bug gives 0
        assertTrue(balanceAfter > 0, "Bug: contract balance became zero");
    }
}

