import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether so it can send money
        vm.deal(address(c), 1 ether);
        // Set up a target that will revert on receive (no fallback)
        address target = address(0x1234);
        vm.deal(target, 0);
        // Call sendMoney with 0.5 ether and empty data; the call will fail because target has no payable fallback
        vm.prank(c.owner());
        c.sendMoney{value: 0 ether}(target, 0.5 ether, "");
        // P requires success → reverts, so the call does not complete
        // M does not require → the call completes silently, but no ETH sent (target balance still 0)
        // We measure depositsCount: in P, since the call reverts, depositsCount is not incremented (still 0)
        // In M, the call fails but does not revert, so depositsCount stays 0 (fallback not called because call failed)
        // Both give same depositsCount? Wait — need divergence: the difference is that P reverts on sendMoney, M does not.
        // So we can test that c.depositsCount() == 0 in both? No, divergence is about reverting vs not.
        // Let's check if the call reverted by using try/catch:
        bool ok;
        try c.sendMoney{value: 0 ether}(target, 0.5 ether, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference P requires => catch is hit => ok = false
        // Bug M does not require => try succeeds => ok = true
        // Assert that ok == false (the reference behavior); bug would make ok == true, failing the test
        assertTrue(!ok, "Reference should revert due to failed call");
    }
}

