pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Target is the zero address, which will cause the call to revert
        address target = address(0);
        uint256 value = 0.5 ether;
        bytes memory data = "";

        bool success;
        try c.sendMoney(target, value, data) {
            success = true;
        } catch {
            success = false;
        }

        // P reverts (success == false), M does not revert (success == true)
        // So we assert that the call reverts, which holds for P but fails for M
        assertTrue(!success);
    }
}
